{
  "@context": "https://schema.org",
  "@type": "TouristTrip",
  "name": "4-Day Sahara Desert Group Tour from Marrakech",
  "description": "A shared, fixed-date group tour from Marrakech — arrival and hostel transfer, then a crossing of the High Atlas via Ait Benhaddou to the Dades Gorges, on to a camel trek and overnight camp in the Sahara desert at Merzouga, before returning to Marrakech.",
  "touristType": ["Budget travelers", "Backpackers", "Solo travelers"],
  "itinerary": {
    "@type": "ItemList",
    "itemListElement": [
      { "@type": "ListItem", "position": 1, "item": { "@type": "TouristAttraction", "name": "Day 1: Arrival in Marrakech", "description": "Airport pick-up and transfer to your hostel in the Marrakech medina. Free time to explore Jemaa el-Fnaa and the surrounding souks." } },
      { "@type": "ListItem", "position": 2, "item": { "@type": "TouristAttraction", "name": "Day 2: Marrakech to Dades Gorges", "description": "Cross the High Atlas via the Tizi n'Tichka pass, stop at the UNESCO-listed Ait Benhaddou kasbah, and continue through the Valley of Roses to an overnight stay in the Dades Gorges." } },
      { "@type": "ListItem", "position": 3, "item": { "@type": "TouristAttraction", "name": "Day 3: Dades Gorges to Merzouga Desert", "description": "Drive via Tinghir and Erfoud to Merzouga, gateway to the Sahara, then a camel ride into the Erg Chebbi dunes to reach your desert camp for the night." } },
      { "@type": "ListItem", "position": 4, "item": { "@type": "TouristAttraction", "name": "Day 4: Merzouga back to Marrakech", "description": "Return drive across the Atlas to Marrakech, with a stop in Ouarzazate. Drop-off at your own accommodation in the city." } }
    ]
  },
  "offers": {
    "@type": "Offer",
    "priceCurrency": "EUR",
    "price": "249",
    "availability": "https://schema.org/InStock"
  },
  "provider": {
    "@type": "TravelAgency",
    "name": "Shared Morocco Adventures",
    "url": "https://www.sharedmoroccoadventures.com"
  }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    { "@type": "Question", "name": "How many people are in the group?", "acceptedAnswer": { "@type": "Answer", "text": "Groups on this route typically run between 6 and 16 travelers, depending on the season." } },
    { "@type": "Question", "name": "Is accommodation shared?", "acceptedAnswer": { "@type": "Answer", "text": "Yes — the €249 price is based on shared twin/dorm rooms in Marrakech and the Dades Gorges, and a shared tent at the desert camp. A private room upgrade is available on request for an additional cost." } },
    { "@type": "Question", "name": "What should I pack for the desert night?", "acceptedAnswer": { "@type": "Answer", "text": "Desert nights get cold even in summer — bring a warm layer, plus sunscreen, a scarf or hat for wind and sun, and comfortable walking shoes." } },
    { "@type": "Question", "name": "Can I join this trip as a solo traveler?", "acceptedAnswer": { "@type": "Answer", "text": "Absolutely — most of our travelers on this route arrive solo. You'll be paired with a same-gender roommate for shared rooms unless you book a private upgrade." } },
    { "@type": "Question", "name": "Where does the tour pick me up and drop me off?", "acceptedAnswer": { "@type": "Answer", "text": "Day 1 includes airport pick-up and transfer to our Marrakech hostel. On Day 4 you're dropped off in Marrakech at your own accommodation — if you haven't booked anywhere yet, we can drop you at the same hostel instead." } },
    { "@type": "Question", "name": "What if the group doesn't fill up?", "acceptedAnswer": { "@type": "Answer", "text": "Unlike many group operators, our departures run on fixed weekly dates regardless of group size — your trip runs even if only a few seats are booked." } }
  ]
}
